namespace gui_forms {

// Ribbon's property capabilities (property-capabilities study, sections
// 2, 14 and 15). Generated by tools/property_codemod.py from
// tools/property_families/ribbon.json: edit the config, not this file.
//
// Each is a standard-layout struct whose only member is its property's
// cell, taken by the declaring class as a base. A write
// `(*control).x = value;` runs `assign`: the declaring class's
// prepare_write hook (require_mutable first, then the value's checks and,
// where C# lets a subclass rewrite the value, the protected virtual coerce
// hook), the compare and store, then the written hook (the touch, side
// effects and the change event, through the protected virtual
// on_<property>_changed() where Windows Forms has OnXChanged). A read is
// `(*control).x.read()`.

// The application modes now shown (one bit per mode; mode 0 by default). Changing them shows the tabs and groups that share a bit; a selected tab that no longer shows gives way as a set's tab does. Zero throws std::invalid_argument.
template <typename Declaring>
struct RibbonApplicationModesCapability {
    PropertyCell<std::uint32_t, RibbonApplicationModesCapability<Declaring>> application_modes{1U};

    static void assign(RibbonApplicationModesCapability& capability, std::uint32_t incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.application_modes), incoming);
        if (!capability.application_modes.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.application_modes));
    }
};

// The document area's declared minimum height in logical units (owner decision 34). The height the ribbon's parent offers it holds the ribbon and the document area under it; the plane hides when that area would be shorter than the minimum, and shows again once it is at least the minimum plus hide_hysteresis. Zero (the default) declares none: the plane hides only when no document area would be left. A negative or non-finite height throws std::invalid_argument.
template <typename Declaring>
struct RibbonDocumentMinimumHeightCapability {
    PropertyCell<double, RibbonDocumentMinimumHeightCapability<Declaring>> document_minimum_height{0.0};

    static void assign(RibbonDocumentMinimumHeightCapability& capability, double incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.document_minimum_height), incoming);
        if (!capability.document_minimum_height.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.document_minimum_height));
    }
};

// Whether the command plane is hidden, leaving the tab row. A change closes the menus and the group overlay and raises minimized_changed.
template <typename Declaring>
struct RibbonMinimizedCapability {
    PropertyCell<bool, RibbonMinimizedCapability<Declaring>> minimized{false};

    static void assign(RibbonMinimizedCapability& capability, bool incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.minimized), incoming);
        if (!capability.minimized.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.minimized));
    }
};

// The File tab's text, with an optional mnemonic. Text that is not valid UTF-8 throws std::invalid_argument.
template <typename Declaring>
struct RibbonApplicationTextCapability {
    PropertyCell<std::string, RibbonApplicationTextCapability<Declaring>> application_text{"File"};

    static void assign(RibbonApplicationTextCapability& capability, std::string incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.application_text), incoming);
        if (!capability.application_text.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.application_text));
    }
};

// The caption of the application menu's recent pane. Text that is not valid UTF-8 throws std::invalid_argument.
template <typename Declaring>
struct RibbonRecentCaptionCapability {
    PropertyCell<std::string, RibbonRecentCaptionCapability<Declaring>> recent_caption{"Recent documents"};

    static void assign(RibbonRecentCaptionCapability& capability, std::string incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.recent_caption), incoming);
        if (!capability.recent_caption.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.recent_caption));
    }
};

// Backstage (phase 6; owner decisions 3, 26): a BackstageView the File tab opens over everything below the tab row, instead of the application menu, or null. Escape, the File tab, another tab or a definitive command closes it and returns to the document. A view that already has a parent throws std::invalid_argument.
template <typename Declaring>
struct RibbonBackstageCapability {
    PropertyCell<std::shared_ptr<BackstageView>, RibbonBackstageCapability<Declaring>> backstage{};

    static void assign(RibbonBackstageCapability& capability, std::shared_ptr<BackstageView> incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.backstage), incoming);
        if (!capability.backstage.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.backstage));
    }
};

// Whether the ribbon adds itself to its window's F6 regions when it is attached (owner decision 17). On by default.
template <typename Declaring>
struct RibbonFocusRegionCapability {
    PropertyCell<bool, RibbonFocusRegionCapability<Declaring>> focus_region{true};

    static void assign(RibbonFocusRegionCapability& capability, bool incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.focus_region), incoming);
        if (!capability.focus_region.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.focus_region));
    }
};

// Every Ribbon capability, in the order the declaring class takes them.
template <typename Declaring>
struct RibbonCapabilities : public RibbonApplicationModesCapability<Declaring>,
                            public RibbonDocumentMinimumHeightCapability<Declaring>,
                            public RibbonMinimizedCapability<Declaring>,
                            public RibbonApplicationTextCapability<Declaring>,
                            public RibbonRecentCaptionCapability<Declaring>,
                            public RibbonBackstageCapability<Declaring>,
                            public RibbonFocusRegionCapability<Declaring>,
                            public FontCapability<Declaring> {
    RibbonCapabilities() : FontCapability<Declaring>(FontSpec{FontRole::control, 10.5, 400, false, 0.12}) {}
};

} // namespace gui_forms
